import copy
import json
import math
from solution import solve


def close(actual, expected):
    if isinstance(expected, bool) or expected is None:
        return actual is expected
    if isinstance(expected, (int, float)):
        return isinstance(actual, (int, float)) and not isinstance(actual, bool) and math.isfinite(actual) and math.isclose(actual, expected, abs_tol=0, rel_tol=0)
    if isinstance(expected, list):
        return isinstance(actual, list) and len(actual) == len(expected) and all(close(a, e) for a, e in zip(actual, expected))
    if isinstance(expected, dict):
        return isinstance(actual, dict) and actual.keys() == expected.keys() and all(close(actual[k], v) for k, v in expected.items())
    return actual == expected


CASES = json.loads("[{\"name\":\"exact_denial_over_prefix\",\"input\":{\"rules\":[{\"principal\":\"*\",\"resource\":\"/reports/*\",\"action\":\"read\",\"effect\":\"allow\"},{\"principal\":\"*\",\"resource\":\"/reports/private\",\"action\":\"read\",\"effect\":\"deny\"}],\"requests\":[{\"principal\":\"alice\",\"resource\":\"/reports/public\",\"action\":\"read\"},{\"principal\":\"alice\",\"resource\":\"/reports/private\",\"action\":\"read\"},{\"principal\":\"alice\",\"resource\":\"/reports/public\",\"action\":\"write\"}]},\"expected\":{\"decisions\":[\"allow\",\"deny\",\"deny\"]}},{\"name\":\"specific_grant\",\"input\":{\"rules\":[{\"principal\":\"*\",\"resource\":\"*\",\"action\":\"*\",\"effect\":\"deny\"},{\"principal\":\"alice\",\"resource\":\"/reports/private\",\"action\":\"read\",\"effect\":\"allow\"}],\"requests\":[{\"principal\":\"alice\",\"resource\":\"/reports/private\",\"action\":\"read\"},{\"principal\":\"bob\",\"resource\":\"/reports/private\",\"action\":\"read\"}]},\"expected\":{\"decisions\":[\"allow\",\"deny\"]}}]")
