def solve(payload):
    rules = payload["rules"]
    for rule in rules:
        resource = rule["resource"]
        pattern_ok = resource == "*" or (resource.startswith("/") and ("*" not in resource or (resource.endswith("/*") and resource.count("*") == 1)))
        if rule["effect"] not in {"allow", "deny"} or not pattern_ok:
            return {"error": "invalid_rule"}
    decisions = []
    for request in payload["requests"]:
        matches = []
        for rule in rules:
            if rule["principal"] not in {"*", request["principal"]} or rule["action"] not in {"*", request["action"]}:
                continue
            pattern, path = rule["resource"], request["resource"]
            if pattern == "*":
                resource_rank = (0, 0)
            elif pattern.endswith("/*"):
                prefix = pattern[:-1]
                if not path.startswith(prefix) or len(path) <= len(prefix):
                    continue
                resource_rank = (1, len(prefix))
            elif pattern == path:
                resource_rank = (2, len(pattern))
            else:
                continue
            rank = resource_rank + (int(rule["principal"] != "*"), int(rule["action"] != "*"))
            matches.append((rank, rule["effect"]))
        if not matches:
            decisions.append("deny")
        else:
            best = max(rank for rank, effect in matches)
            decisions.append("deny" if any(rank == best and effect == "deny" for rank, effect in matches) else "allow")
    return {"decisions": decisions}

